/* Authored usage studies. Examples are original teaching sentences, not textbook quotations. */
(() => {
 'use strict';
 const rows=[];
 const add=(han,usage,formation,contrast,bridge,a,b)=>rows.push({han,usage,formation,contrast,bridge,examples:[a,b]});
 add('就','Trong 就是, 就 đặt trọng tâm vào sự xác nhận: đúng người ấy, chính vật ấy. Đọc liền với 是, không tìm một đồ vật mang nghĩa “chính”.','就 là một chữ, đồng thời có thể làm phó từ trong câu; phân tích nét chữ không giải thích được mọi chức năng ngữ pháp.','就是 xác nhận mạnh hơn 是. Trong một câu khác, 就 có thể nói sự tiếp nối hoặc xảy ra sớm; không mang nghĩa “chính” sang mọi chỗ.','“Tựu” trong thành tựu giúp nhận chữ; không dùng thành tựu để suy nghĩa phó từ 就.', ['你就是王先生吧？','Nǐ jiù shì Wáng xiānsheng ba?','Bạn chính là ông Vương, phải không?'],['我要的就是这本书。','Wǒ yào de jiù shì zhè běn shū.','Cuốn sách tôi muốn chính là cuốn này.']);
 add('给','给 + người + động từ nêu người nhận hoặc người được hướng tới. Trong 给你打电话, cuộc gọi hướng tới 你.','Một chữ có hai khung thường gặp: động từ 给你一本书 và giới từ trong 给你打电话. Xác định phần sau trước khi dịch.','我给你一本书 là tôi đưa bạn một cuốn sách; 我给你买书 là tôi mua sách cho bạn, chưa khẳng định đã giao sách.','“Cấp” trong cung cấp là một điểm đối chiếu; gěi ở đây là cách đọc Quan thoại.', ['我给你打电话。','Wǒ gěi nǐ dǎ diànhuà.','Tôi gọi điện cho bạn.'],['我给妈妈买了一杯奶茶。','Wǒ gěi māma mǎi le yì bēi nǎichá.','Tôi mua cho mẹ một cốc trà sữa.']);
 add('让','让 + người + việc phải làm. Người đứng sau 让 là người thực hiện động từ sau đó.','Đây là cấu trúc của câu, không phải một từ ghép: trong 让我介绍, 我 vừa là người được cho phép/yêu cầu vừa là người giới thiệu.','让我介绍 có thể là “để tôi giới thiệu”; 妈妈让我回家 thường là “mẹ bảo tôi về”. Lời nói và tình huống quyết định sắc thái cho phép hay yêu cầu.','让 viết phồn thể 讓; “nhượng” trong nhượng bộ giúp nhớ ý cho người khác một phần quyền thực hiện.', ['让我介绍一下。','Ràng wǒ jièshào yíxià.','Để tôi giới thiệu một chút.'],['老师让我们读课文。','Lǎoshī ràng wǒmen dú kèwén.','Thầy cô yêu cầu chúng tôi đọc bài khóa.']);
 add('接','接人 là đón người ở một điểm hẹn; 接电话 là nghe/nhận cuộc gọi. Cần đọc cả tân ngữ.','接 có 扌 ở bên trái trong hình hiện đại. Liên hệ với tay giúp nhận mặt, nhưng không đủ để suy riêng nghĩa của 接电话.','去车站接你 nêu việc đến đón; 送你去车站 nêu việc đưa bạn tới ga. Cùng nhà ga, hướng phục vụ khác nhau.','“Tiếp” gặp trong tiếp nhận, tiếp khách; khi dịch phải chọn đón, nhận hoặc nghe theo vật được tiếp.', ['我去车站接你。','Wǒ qù chēzhàn jiē nǐ.','Tôi đến ga đón bạn.'],['她正在接电话。','Tā zhèngzài jiē diànhuà.','Cô ấy đang nghe điện thoại.']);
 add('次','Số + 次 đếm số lần một việc xảy ra; 第一次 xếp thứ tự một lần trong chuỗi.','次 là lượng từ của sự kiện trong các câu này, không phải lượng từ đếm người hay đồ vật.','去过两次 nói hai lần đã từng đi; 第二次去 chọn lần thứ hai, không khẳng định toàn bộ lịch sử chỉ có hai lần.','“Thứ” trong thứ tự gần với 第一次; cách dùng 次 đếm lần cần học thêm trong câu.', ['我去过两次北京。','Wǒ qù guo liǎng cì Běijīng.','Tôi từng đến Bắc Kinh hai lần.'],['这是我第一次来这里。','Zhè shì wǒ dì yī cì lái zhèlǐ.','Đây là lần đầu tôi đến đây.']);
 add('旅游','去 + địa điểm + 旅游: đến đâu để du lịch. Khi hỏi dự định có thể dùng 想去…旅游.','旅 và 游 đều liên quan đến việc đi, nhưng 旅游 là tên hoạt động đã thành từ. Không phải mọi hành động đi lại đều là 旅游.','去北京旅游 nêu mục đích chuyến đi; 在北京工作 là làm việc ở đó. Đều có thể phải đi xa nhưng mục đích khác.','旅 là “lữ” trong lữ hành, 游 là “du” trong du lịch; từ Việt du lịch không có cùng thứ tự mặt chữ với 旅游.', ['我想去西安旅游。','Wǒ xiǎng qù Xī’ān lǚyóu.','Tôi muốn đến Tây An du lịch.'],['她来中国工作，不是来旅游的。','Tā lái Zhōngguó gōngzuò, bú shì lái lǚyóu de.','Cô ấy sang Trung Quốc làm việc, không phải đi du lịch.']);
 add('帮忙','请你帮忙 là nhờ bạn giúp; 帮我一个忙 là nhờ giúp một việc cụ thể. Có thể tách cụm khi thêm người hay lượng từ.','Không đọc 忙 theo nghĩa tính từ “bận” rồi dịch 帮忙 thành giúp bận. Cả cụm mang nghĩa giúp một tay; dạng 帮一个忙 cho thấy cách dùng có thể tách.','帮我买票 đặt 我 giữa 帮 và việc cần làm. Không cần chèn 忙 vào mọi câu dùng 帮.','“Bang” của 帮 ít thông dụng trong lời Việt; dùng cụm giúp một tay làm điểm tựa nghĩa.', ['你能帮我一个忙吗？','Nǐ néng bāng wǒ yí ge máng ma?','Bạn có thể giúp tôi một việc không?'],['请你帮我买票。','Qǐng nǐ bāng wǒ mǎi piào.','Nhờ bạn mua vé giúp tôi.']);
 add('不好意思','Dùng để mở lời khi làm phiền, nhận một sơ suất hoặc diễn tả sự ngại ngùng; không phải lúc nào cũng là nhận lỗi nghiêm trọng.','Cụm đã thành cách nói quy ước. Biết 不、好、意思 riêng vẫn chưa đủ suy ra công dụng xin phép mở lời.','不好意思，请问… mở câu hỏi lịch sự; 对不起 phù hợp hơn khi cần xin lỗi rõ về việc gây hại hoặc mắc lỗi. Phạm vi hai cách nói có phần giao nhau.','“Ý tứ” gần chữ 意思 về âm Hán Việt, nhưng 不好意思 không dịch thành “ý tứ không tốt”.', ['不好意思，请问车站在哪儿？','Bù hǎoyìsi, qǐngwèn chēzhàn zài nǎr?','Xin lỗi làm phiền, cho hỏi nhà ga ở đâu?'],['我有点儿不好意思。','Wǒ yǒudiǎnr bù hǎoyìsi.','Tôi hơi ngại.']);
 add('已经','Đặt trước động từ hoặc trạng thái để nói điều đã xảy ra/đạt tới trước mốc đang xét. 已经…了 thường đi cùng nhau.','Học 已经 như một phó từ hai chữ. Không tách 经 rồi đem nghĩa kinh điển hay kinh doanh áp vào đây.','已经吃了 là đã ăn; 还没吃 là vẫn chưa ăn. Trong câu phủ định thường đổi khung, không ghép 已经 với 没 một cách máy móc.','经 là “kinh” trong kinh nghiệm; đó là liên hệ nhận chữ, không phải bản dịch của 已经.', ['我已经买好票了。','Wǒ yǐjīng mǎihǎo piào le.','Tôi đã mua xong vé rồi.'],['他已经二十岁了。','Tā yǐjīng èrshí suì le.','Anh ấy đã hai mươi tuổi rồi.']);
 add('那','Đầu câu, 那 có thể nối kết luận/đề nghị với điều vừa biết: “vậy thì”. Trước danh từ, 那 lại chỉ “đó/kia”.','Cùng một chữ nhưng vị trí trong phát ngôn đổi vai trò: nối lượt lời hoặc xác định một đối tượng.','那我们走吧 tiếp nhận thông tin rồi đề nghị đi; 那个人 chỉ một người ở xa hoặc đã được nhắc.','Không cần ép một âm Hán Việt để học trợ từ nối lời này; hãy giữ hai khung câu cạnh nhau.', ['那我们明天去吧。','Nà wǒmen míngtiān qù ba.','Vậy ngày mai chúng ta đi nhé.'],['那个人是我的老师。','Nà ge rén shì wǒ de lǎoshī.','Người kia là giáo viên của tôi.']);
 add('介绍','介绍 A 给 B hoặc 给 B 介绍 A xác định người được giới thiệu và người nhận thông tin. 介绍一下自己 là tự giới thiệu.','介绍 là động từ hai chữ đã quy ước. Tách để nhận 介、绍 không tự chứng minh nghĩa và khung tân ngữ của cả từ.','介绍我的朋友 có thể giới thiệu người bạn; 给朋友介绍学校 là giới thiệu trường cho bạn. Đổi vị trí làm đổi vai của 朋友.','“Giới thiệu” là một từ Hán Việt đang dùng thực sự, tương ứng trực tiếp với 介绍.', ['我给你介绍一下我的朋友。','Wǒ gěi nǐ jièshào yíxià wǒ de péngyou.','Tôi giới thiệu với bạn một người bạn của tôi nhé.'],['请介绍一下你自己。','Qǐng jièshào yíxià nǐ zìjǐ.','Bạn hãy tự giới thiệu một chút.']);
 add('有时','Đặt trước hành động để chỉ đôi khi. Có thể tổ chức hai khả năng bằng 有时…有时….','有 + 时 tạo một biểu thức thời gian: có những lúc. Ở đây 有 không mở một câu sở hữu đồ vật.','有时 ở đầu/vị trí trạng ngữ nói tần suất; 有时间 nói có thời gian rảnh, không đồng nghĩa với đôi khi.','时 là “thời” trong thời gian; cụm “có lúc” giúp nhận cách ghép nghĩa.', ['我有时坐公交车上班。','Wǒ yǒushí zuò gōngjiāochē shàngbān.','Đôi khi tôi đi làm bằng xe buýt.'],['我今天有时间。','Wǒ jīntiān yǒu shíjiān.','Hôm nay tôi có thời gian.']);
 add('懂','Hiểu lời nói, nội dung hoặc cách vận hành. 听懂 nhấn kết quả nghe hiểu; 看懂 nhấn đọc/nhìn hiểu.','懂 là một chữ; trong 听懂 và 看懂 nó làm phần kết quả. Đừng gán cho mọi chữ có 忄 cùng một nghĩa tâm lý cụ thể.','听到了 chỉ nghe thấy âm; 听懂了 thêm việc hiểu nội dung. Hai kết quả không tự đi cùng nhau.','Âm “đổng” ít dùng làm điểm tựa độc lập; cặp nghe thấy/nghe hiểu hữu ích hơn.', ['我听见了，但是没听懂。','Wǒ tīngjiàn le, dànshì méi tīngdǒng.','Tôi nghe thấy nhưng chưa hiểu.'],['这个字我看得懂。','Zhè ge zì wǒ kàn de dǒng.','Chữ này tôi đọc hiểu được.']);
 add('意思','意思 có thể là nghĩa của từ, ý định của người nói hoặc điều muốn diễn đạt. Xem ai/sự vật nào có “ý”.','Học như danh từ hai chữ; trong 有意思 cả cụm trở thành nhận xét “thú vị”, không chỉ “có nghĩa”.','这个词是什么意思 hỏi nghĩa từ; 我的意思是… làm rõ điều mình định nói. 有意思 và 不好意思 là hai kết hợp đã có công dụng riêng.','“Ý tứ” giúp nhận quan hệ chữ, nhưng tiếng Việt thường dịch là nghĩa, ý, ý định tùy câu.', ['这个词是什么意思？','Zhè ge cí shì shénme yìsi?','Từ này nghĩa là gì?'],['我的意思是，我们明天再去。','Wǒ de yìsi shì, wǒmen míngtiān zài qù.','Ý tôi là ngày mai chúng ta hãy đi.']);
 add('还是','Ở bài này, 还是…吧 đưa ra phương án người nói cho là nên chọn sau khi cân nhắc.','还是 còn là thành phần của câu hỏi lựa chọn. Cần nhìn dấu hỏi, hai phương án và 吧 thay vì chỉ dịch một nghĩa “hay là”.','你坐车还是走路？ đòi chọn giữa hai phương án. 我们还是坐车吧 là đề nghị chọn đi xe.','Đừng dùng “hoàn thị” làm lời dịch; cách nói Việt hay là/nên…thì hơn phụ thuộc kiểu câu.', ['我们还是打车去吧。','Wǒmen háishi dǎchē qù ba.','Hay là chúng ta bắt taxi đi nhé.'],['你喝茶还是喝水？','Nǐ hē chá háishi hē shuǐ?','Bạn uống trà hay uống nước?']);
 add('打车','打车 là đi bằng taxi/xe gọi dịch vụ. 坐车 bao quát việc đi xe hơn, không nhất thiết là taxi.','打 kết hợp với danh từ phương tiện thành động từ quy ước; không dịch nghĩa cơ bản “đánh” vào cụm này.','我打车去说明 cách đi bằng xe dịch vụ; 我开车去 nêu mình lái xe.','车 là “xa” trong xa lộ. Cần học cả cụm để chọn đúng vai hành khách hay người lái.', ['车站很远，我们打车去吧。','Chēzhàn hěn yuǎn, wǒmen dǎchē qù ba.','Ga khá xa, chúng ta bắt taxi đi nhé.'],['今天我不开车，我打车去公司。','Jīntiān wǒ bù kāichē, wǒ dǎchē qù gōngsī.','Hôm nay tôi không tự lái xe, tôi đi taxi tới công ty.']);
 add('公交车','上公交车、坐公交车lần lượt nói lên xe và đi bằng xe buýt. Khi đếm dùng 辆, không lấy 个 làm mẫu chính.','公交 là cách rút gọn của 公共交通, 车 nêu loại phương tiện. Đây là giải thích tên gọi hiện đại, không phải lịch sử tạo từng chữ.','公交车 chạy theo tuyến; 出租车 là taxi. Có 车 chung không có nghĩa dùng cùng cách bắt hoặc trả phí.','公 tương ứng “công” trong công cộng; phần nghĩa ấy giúp nhớ phương tiện giao thông công cộng.', ['我每天坐公交车上学。','Wǒ měitiān zuò gōngjiāochē shàngxué.','Hằng ngày tôi đi học bằng xe buýt.'],['那辆公交车到火车站吗？','Nà liàng gōngjiāochē dào huǒchēzhàn ma?','Xe buýt kia có tới ga tàu không?']);
 add('车站','Địa điểm phương tiện dừng đón trả khách. Cần từ đứng trước để biết ga tàu, bến xe buýt hay loại trạm khác.','车 chỉ phương tiện; 站 trong từ này chỉ trạm. Cùng 站 nhưng 他站着 lại là động từ đứng.','在车站等人 là ở ga chờ người; 站在门口 là đứng ở cửa. Vai của 站 đổi theo tổ hợp và vị trí.','“Xa trạm” chỉ là ghép âm đối chiếu; tiếng Việt dùng nhà ga, bến hoặc trạm.', ['我在车站等你。','Wǒ zài chēzhàn děng nǐ.','Tôi đợi bạn ở ga.'],['去火车站的车来了。','Qù huǒchēzhàn de chē lái le.','Xe đi ga tàu đến rồi.']);
 add('远','Xa là quan hệ giữa hai mốc; 离 A 远 nêu mốc A để người nghe biết xa so với đâu.','远 là tính từ trong các câu này. Không cần 是 trước nhận xét đơn giản 很远.','车站离学校远 so ga với trường; 车站在学校前边 nói vị trí phía trước, chưa nói khoảng cách xa hay gần.','“Viễn” trong viễn cảnh, viễn thông giúp nhận ý xa; phát âm Quan thoại là yuǎn.', ['车站离我家很远。','Chēzhàn lí wǒ jiā hěn yuǎn.','Ga cách nhà tôi khá xa.'],['这里离学校不远。','Zhèlǐ lí xuéxiào bù yuǎn.','Chỗ này cách trường không xa.']);
 add('别','别 + hành động là lời ngăn: đừng làm việc đó. 可以/不可以 nêu cho phép, còn 别 trực tiếp hướng người nghe.','别 có nghĩa khác trong 别人 hoặc 别的. Cùng chữ nhưng không gom chức năng ngăn cấm vào mọi tổ hợp.','别走 là đừng đi/rời đi; 不走 có thể đơn thuần nói ai đó không đi, chưa chắc là mệnh lệnh.','“Biệt” trong phân biệt thuộc một nghĩa khác; dùng mẫu lời ngăn để học nghĩa này.', ['别忘了带票。','Bié wàng le dài piào.','Đừng quên mang vé.'],['别在这里等，我们去里面吧。','Bié zài zhèlǐ děng, wǒmen qù lǐmian ba.','Đừng đợi ở đây, chúng ta vào trong nhé.']);
 add('但','Nối vế sau trái với dự đoán từ vế trước: tuy có điều kiện A nhưng vẫn có B. 但是 là dạng dài thường gặp.','Đây là quan hệ giữa hai vế, không phải một động tác có thể minh họa bằng việc tách nét 亻 bên trái.','因为…所以… nối nguyên nhân/kết quả; …但… nêu sự tương phản. “Xa nhưng đi bộ” khác “xa nên đi xe”.','“Đãn” ít dùng trong lời Việt; ghi nhớ quan hệ nhưng giữa hai mệnh đề.', ['学校很远，但我想走路去。','Xuéxiào hěn yuǎn, dàn wǒ xiǎng zǒulù qù.','Trường khá xa nhưng tôi muốn đi bộ tới.'],['我认识这个字，但不会写。','Wǒ rènshi zhè ge zì, dàn bú huì xiě.','Tôi nhận ra chữ này nhưng chưa biết viết.']);
 add('啊','Trợ từ cuối câu làm rõ giọng cảm thán, nhắc, hỏi hoặc đáp thân mật; sức biểu đạt tùy ngữ điệu.','啊 là một âm tiết trợ từ. Cách đọc nối trong lời nói có thể biến đổi theo âm trước; không lấy một giọng TTS làm quy tắc cho mọi trường hợp.','真好啊！ cảm thán trước điều tốt; 好吗？ hỏi ý kiến. Đổi trợ từ có thể đổi hành vi lời nói.','Không cần dịch 啊 thành một từ cố định; tiếng Việt có thể dùng quá, nhỉ, à hoặc để giọng nói đảm nhiệm.', ['这里真漂亮啊！','Zhèlǐ zhēn piàoliang a!','Ở đây đẹp thật!'],['你也在这里啊！','Nǐ yě zài zhèlǐ a!','Bạn cũng ở đây à!']);
 add('万','Một 万 bằng 10.000. Đếm số lớn theo nhóm vạn rồi mới ghép 千、百、十.','万 là đơn vị số, không phải lượng từ của đồ vật; sau số tiền còn có thể có 块、元.','一万 là mười nghìn; 十万 là một trăm nghìn. Không chuyển từng nhóm ba chữ số tiếng Việt sang nhóm Trung một cách máy móc.','“Vạn” trong vạn sự, vạn người là cầu trực tiếp nhưng có lúc chỉ số nhiều ước lệ trong văn chương.', ['这辆车十万元。','Zhè liàng chē shí wàn yuán.','Chiếc xe này giá một trăm nghìn nhân dân tệ.'],['一万加一千是一万一千。','Yí wàn jiā yì qiān shì yí wàn yì qiān.','Mười nghìn cộng một nghìn bằng mười một nghìn.']);
 add('名','Một lượng từ đếm người thường gặp khi nêu số người thuộc nhóm, nghề hoặc danh sách.','名 trong 三名学生 là lượng từ; 名 trong 名字 là một phần của từ chỉ tên. Không lẫn hai khung.','三名学生 hợp thông báo số học sinh. 三位老师 thêm sắc thái kính trọng; 三个学生 phổ biến trong lời thường.','“Danh” trong danh sách, danh tính giúp nhận chữ; 名 ở khung này dịch bằng người/bạn/vị theo danh từ.', ['我们班有二十名学生。','Wǒmen bān yǒu èrshí míng xuésheng.','Lớp chúng tôi có hai mươi học sinh.'],['三名老师正在开会。','Sān míng lǎoshī zhèngzài kāihuì.','Ba giáo viên đang họp.']);
 add('外国','Chỉ các nước khác với nước lấy làm mốc. Mốc thường là đất nước của người nói/bối cảnh đang xét.','外 bổ nghĩa cho 国: nước ở bên ngoài mốc. 外国人 thêm 人 để gọi người nước ngoài.','外国 là danh từ nước ngoài; 在国外 là ở ngoài nước. Thứ tự chữ và vị trí trong câu khác nhau.','国 là “quốc” trong quốc gia, 外 là “ngoại” trong ngoại quốc; cách nói Việt nước ngoài tự nhiên hơn trong hội thoại.', ['她想去外国学习。','Tā xiǎng qù wàiguó xuéxí.','Cô ấy muốn ra nước ngoài học.'],['这个班有几名外国学生？','Zhè ge bān yǒu jǐ míng wàiguó xuésheng?','Lớp này có mấy học sinh nước ngoài?']);
 add('教室','Phòng dành cho việc dạy và học; 进教室、在教室里 chọn lần lượt hướng đi vào và vị trí trong phòng.','教 nêu việc dạy/học, 室 nêu phòng; đây là ghép nghĩa hiện đại. Trong 教室 đọc jiào, còn động từ “dạy” như 教汉语 thường đọc jiāo.','教室 là phòng học, không phải 教师 là giáo viên. Chỉ đổi một chữ cuối đã đổi từ địa điểm sang người.','“Giáo thất” là đối chiếu chữ, không phải tên phòng quen dùng trong tiếng Việt; nhớ giáo trong giáo dục, thất trong thư thất.', ['学生们在教室里看书。','Xuéshengmen zài jiàoshì lǐ kàn shū.','Các học sinh đọc sách trong lớp.'],['这间教室很大。','Zhè jiān jiàoshì hěn dà.','Phòng học này rất rộng.']);
 add('间','Trong bài, 间 đứng giữa số/chỉ từ và danh từ chỉ phòng: 一间教室、这间房.','Lượng từ 间 jiān khác chữ trong 时间 shíjiān về nhiệm vụ ngữ pháp, dù cùng cách viết.','一间教室 đếm phòng; 一个老师 đếm người. Chọn lượng từ từ loại đối tượng, không từ số lượng ít hay nhiều.','“Gian” trong gian phòng là điểm tựa trực tiếp.', ['我想订一间房。','Wǒ xiǎng dìng yì jiān fáng.','Tôi muốn đặt một phòng.'],['那间教室里有多少人？','Nà jiān jiàoshì lǐ yǒu duōshao rén?','Trong phòng học kia có bao nhiêu người?']);
 add('网上','Dùng 在网上 + việc làm để nói thực hiện trên mạng. 上 ở đây định vị trong một môi trường, không nhất thiết trên bề mặt vật lý.','网 chỉ mạng/lưới, 上 tạo vị trí; cách kết hợp tương tự 在桌上 về chức năng định vị nhưng khác loại không gian.','我在网上买票 là mua vé qua mạng; 我在车站买票 là mua tại ga. Thay địa điểm trước động từ.','网 là “võng” trong thiên la địa võng, nhưng lời Việt hiện đại dùng mạng; 网上 không dịch thành võng thượng.', ['我在网上买了两张票。','Wǒ zài wǎngshang mǎi le liǎng zhāng piào.','Tôi mua hai vé trên mạng.'],['网上说这家饭店不错。','Wǎngshang shuō zhè jiā fàndiàn búcuò.','Trên mạng nói nhà hàng này khá tốt.']);
 add('票','Vé cho một chuyến đi, buổi diễn hoặc dịch vụ; nói 买票、车票 và dùng 张 để đếm tấm vé.','票 là danh từ một chữ ở đây. Trong 车票, phần 车 xác định loại vé, không phải chủ sở hữu của vé.','一张车票 là một vé xe; 一辆车 là một chiếc xe. Cùng 车 nhưng danh từ trung tâm khác.','“Phiếu” trong phiếu bầu, cổ phiếu giúp nhận chữ; nghĩa vé cần xác định qua tổ hợp.', ['我要买一张去北京的票。','Wǒ yào mǎi yì zhāng qù Běijīng de piào.','Tôi muốn mua một vé đi Bắc Kinh.'],['请把票拿出来。','Qǐng bǎ piào ná chūlái.','Bạn vui lòng lấy vé ra.']);
 add('过来','Di chuyển qua/đến phía mốc nói năng. 来 định hướng về phía người nói hoặc điểm nhìn đang được chọn.','过 + 来 là tổ hợp động từ hướng. Nếu tách 来 khỏi mốc nhìn, chỉ nhớ hai nghĩa “qua/đến” sẽ chưa chọn được đúng hướng.','过来 hướng về đây; 过去 hướng qua bên kia, rời mốc hiện tại. Người ở hai phía có thể dùng từ khác cho cùng một chuyến đi.','来 là “lai” trong tương lai; khi học hướng hãy đặt người nói vào sơ đồ trước.', ['请到这边来，慢慢走过来。','Qǐng dào zhè biān lái, mànmàn zǒu guòlái.','Hãy sang bên này, từ từ đi qua đây.'],['我在门口，你过来吧。','Wǒ zài ménkǒu, nǐ guòlái ba.','Tôi ở cửa, bạn qua đây nhé.']);
 add('回来','回 giữ ý trở về; 来 cho biết trở về phía điểm nhìn. Có thể dùng nhà/người nói làm mốc.','Hai yếu tố góp hai thông tin: hồi quy về nơi trước đó và hướng về đây. Không giản lược 回来 thành mọi trường hợp “về”.','Người đang ở nhà nói 你什么时候回来？; người ở nơi khác có thể hỏi 你什么时候回去？. Không phải ngày tháng làm đổi 来/去 mà là điểm nhìn.','“Hồi” trong hồi hương gợi ý trở về; 来 thêm hướng về mốc nói.', ['你什么时候回来？','Nǐ shénme shíhou huílái?','Khi nào bạn về đây?'],['爸爸回来了，我们去开门吧。','Bàba huílái le, wǒmen qù kāi mén ba.','Bố về rồi, chúng ta ra mở cửa nhé.']);
 add('回去','Trở về nơi khác với phía người nói/điểm nhìn. Đọc 回 để biết trở về, 去 để biết hướng đi khỏi đây.','回 + 去 là một tổ hợp chỉ hướng; không phải hai địa điểm. Có thể nói 回家去 với nơi trở về ở giữa.','我在家等你回来: tôi ở nhà đợi bạn về. 我送你回去: tôi đưa bạn về chỗ của bạn.','“Hồi” giúp nhận việc trở về, nhưng không quyết định được 回来 hay 回去.', ['太晚了，我要回去了。','Tài wǎn le, wǒ yào huíqù le.','Muộn rồi, tôi phải về thôi.'],['我送你回家去。','Wǒ sòng nǐ huí jiā qù.','Tôi đưa bạn về nhà.']);
 add('出去','Ra khỏi nơi bên trong và đi xa phía điểm nhìn. Có thể đặt nơi chốn giữa 出 và 去: 出门去.','出 biểu đạt ra khỏi; 去 biểu đạt hướng đi khỏi mốc. Một phần chọn biên giới trong/ngoài, phần kia chọn hướng đối với người nói.','Người trong phòng nói 你出去吧; người ngoài cửa có thể nói 你出来吧. Cùng bước qua cửa nhưng điểm nhìn khác.','“Xuất” trong xuất nhập giúp nhớ ra/vào; “khứ” không phải từ giao tiếp Việt để dịch cả cụm.', ['我想出去买点儿东西。','Wǒ xiǎng chūqù mǎi diǎnr dōngxi.','Tôi muốn ra ngoài mua ít đồ.'],['他出去了，现在不在家。','Tā chūqù le, xiànzài bú zài jiā.','Anh ấy đi ra ngoài rồi, hiện không ở nhà.']);
 add('一起','Đặt trước hành động để nói hai hay nhiều người làm cùng nhau. Có thể nêu người cùng bằng 跟/和.','Học 一起 như một trạng ngữ; chữ 起 trong tổ hợp này không còn đơn thuần là đứng dậy.','一起去 là cùng đi; 一起到 không nhất thiết cùng phương tiện từ đầu nếu bối cảnh chỉ nói đến nơi cùng lúc. Cần đọc hành động cụ thể.','“Cùng nhau” là nghĩa dùng, không thay bằng nhất khởi từ âm từng chữ.', ['我们一起去旅游吧。','Wǒmen yìqǐ qù lǚyóu ba.','Chúng ta cùng đi du lịch nhé.'],['我想跟你一起吃饭。','Wǒ xiǎng gēn nǐ yìqǐ chī fàn.','Tôi muốn ăn cơm cùng bạn.']);
 add('每','每 + lượng từ/danh từ thời gian + danh từ: 每个学生、每天. 都 thường xuất hiện ở vế sau để nói điều đúng với từng thành viên.','每 chọn từng phần tử trong một tập hợp, khác số nhiều gộp chung. Với 天 không cần 个.','每天说的是 từng ngày; 今天只 nói ngày hôm nay. 每个学生都有书 xác nhận từng người có sách, không chỉ nhóm có vài cuốn chung.','“Mỗi” là điểm tựa nghĩa trực tiếp; âm Hán Việt của 每 là mỗi.', ['我每天都洗手很多次。','Wǒ měitiān dōu xǐ shǒu hěn duō cì.','Mỗi ngày tôi rửa tay nhiều lần.'],['每个学生都要准备一本书。','Měi ge xuésheng dōu yào zhǔnbèi yì běn shū.','Mỗi học sinh đều cần chuẩn bị một cuốn sách.']);
 add('完','Sau động từ, 完 báo đã làm đến hết phạm vi việc đó: 吃完、看完、写完. Có thể nhấn chưa đạt kết quả bằng 没…完.','Động từ + bổ ngữ kết quả là một cấu trúc, không phải mọi tổ hợp đều là mục từ cố định cần dịch từng chữ.','我看了这本书 chỉ xác nhận đã đọc/cuốn sách có liên quan; 我看完了这本书 xác nhận đọc hết. 了 không tự thay được 完.','“Hoàn” trong hoàn tất giúp nhớ kết thúc; đừng nhầm với 还 hái/huán, khác chữ.', ['我看完这本书了。','Wǒ kànwán zhè běn shū le.','Tôi đọc xong cuốn sách này rồi.'],['饭还没吃完，别走。','Fàn hái méi chīwán, bié zǒu.','Cơm vẫn chưa ăn xong, đừng đi.']);
 add('洗','洗 + vật cần rửa/giặt: 洗手、洗衣服. Vật đi sau quyết định tiếng Việt dùng rửa hay giặt.','氵 là thành phần nước có thể nhận trên hình chữ; phần nhận diện này không tự cho biết toàn bộ các nghĩa của động từ.','洗手 rửa tay, 洗衣服 giặt quần áo. Không đổi nghĩa động từ chỉ vì hai đối tượng cùng thuộc một người.','“Tẩy” trong tẩy rửa là liên hệ Hán Việt hữu ích; tiếng Việt không nói tẩy tay trong hội thoại thường.', ['吃饭以前要洗手。','Chī fàn yǐqián yào xǐ shǒu.','Trước khi ăn cần rửa tay.'],['我正在洗衣服。','Wǒ zhèngzài xǐ yīfu.','Tôi đang giặt quần áo.']);
 add('手','Bộ phận cơ thể: dùng trong 洗手、左手、右手. Vào từ ghép, 手 có thể chỉ người thành thạo một việc như 歌手.','Một chữ có nghĩa bộ phận cơ thể và các nghĩa phát triển trong từ ghép. Nghĩa cả từ cần kiểm tra trước khi suy từ bàn tay.','手 là bàn tay; 手机 là điện thoại di động, không phải một bàn tay có máy móc.','“Thủ” trong thủ công là làm bằng tay; tay nghề là một cầu nghĩa dễ nhớ.', ['请用右手拿画笔。','Qǐng yòng yòu shǒu ná huàbǐ.','Bạn hãy dùng tay phải cầm bút vẽ.'],['他的手很冷。','Tā de shǒu hěn lěng.','Tay anh ấy rất lạnh.']);
 add('自己','Có thể nhấn tự bản thân thực hiện hoặc quy chiếu trở lại một người đã nêu. Xác định chủ thể trước.','自己 là đại từ phản thân; không phải cụm sở hữu “của tôi” trong mọi câu. Từ đứng trước làm rõ ai là bản thân.','我自己做 là chính tôi tự làm; 我自己的书 là sách của chính tôi. 的 đánh dấu quan hệ bổ nghĩa trong cụm danh từ.','“Tự kỷ” có cùng chữ 自己 nhưng trong tiếng Việt hiện đại còn là thuật ngữ khác; không dùng nó để dịch mọi 自己.', ['这张画是我自己画的。','Zhè zhāng huà shì wǒ zìjǐ huà de.','Bức tranh này do chính tôi vẽ.'],['每个人都有自己的想法。','Měi ge rén dōu yǒu zìjǐ de xiǎngfǎ.','Mỗi người đều có suy nghĩ của mình.']);
 add('拿','Cầm hoặc lấy đồ bằng tay; 拿来/拿去 thêm hướng đưa đồ về đây hoặc đi chỗ khác.','拿 ở đây là động từ, không phải lượng từ. Học động từ với vật đi sau và hướng của vật.','拿书 cầm/lấy sách; 买书 mua sách. 拿 chưa cho biết sở hữu hay đã trả tiền.','Âm Hán Việt “nã” gặp trong vài tổ hợp ít dùng; cặp cầm/lấy phù hợp hơn cho nghĩa đang học.', ['请把书拿过来。','Qǐng bǎ shū ná guòlái.','Bạn vui lòng mang sách qua đây.'],['他拿着一份礼物。','Tā názhe yí fèn lǐwù.','Anh ấy đang cầm một món quà.']);
 add('为什么','Hỏi nguyên nhân, thường đứng trước vị ngữ. Câu trả lời có thể mở bằng 因为.','为 trong 为什么 giới thiệu điều được hỏi; không lấy nghĩa “là” của 为 trong cổ văn để dịch câu hỏi hiện đại.','为什么 hỏi lý do; 怎么去 hỏi cách đi. “Vì sao đi” và “đi như thế nào” cần hai câu trả lời khác nhau.','“Vì sao/tại sao” là nghĩa cả cụm. Hán Việt của từng chữ không tạo thành cách hỏi Việt tự nhiên.', ['你为什么想去西安？','Nǐ wèi shénme xiǎng qù Xī’ān?','Vì sao bạn muốn đến Tây An?'],['他今天为什么这么累？','Tā jīntiān wèi shénme zhème lèi?','Hôm nay vì sao anh ấy mệt như vậy?']);
 add('这么','Đứng trước tính từ hoặc cách làm để chỉ mức độ/cách thức đang được thấy hoặc nhắc gần: 这么远、这么写.','这 gắn với điểm chỉ “này”; 么 thuộc biểu thức quy ước. Không đọc cấu tạo nét như lời giải cho nghĩa mức độ.','这么远 thường gắn với khoảng cách đang cảm nhận; 那么远 có thể hướng tới mức độ xa hoặc câu chuyện đã nêu. Cả hai cần mốc trong ngữ cảnh.','Dịch như thế này/đến vậy theo vị trí; không cố ghép âm từng chữ.', ['这里为什么这么热？','Zhèlǐ wèi shénme zhème rè?','Sao ở đây nóng thế?'],['这个字不能这么写。','Zhè ge zì bù néng zhème xiě.','Chữ này không thể viết như thế này.']);
 add('不错','Nhận xét khá tốt, không tệ. Dạng phủ định của 错 đã thành một lời đánh giá tích cực trong nhiều ngữ cảnh.','不 + 错 có thể hiểu theo nghĩa phủ định sai, nhưng cả cụm cũng là lời khen có mức độ; nghe giọng và điều được đánh giá.','这家饭店不错 khen nhà hàng; 这个答案没错 xác nhận đáp án không sai. Lời khen và kiểm tra đúng/sai không hoàn toàn giống nhau.','错 là “thác” trong sai thác, ít dùng; hãy ghi cụm không tệ làm điểm tựa.', ['这家饭店的菜不错。','Zhè jiā fàndiàn de cài búcuò.','Món ăn ở nhà hàng này khá ngon.'],['你今天读得不错。','Nǐ jīntiān dú de búcuò.','Hôm nay bạn đọc khá tốt.']);
 add('送','送 + người/vật có thể là tặng, giao/đưa hoặc tiễn. Xác định đối tượng và điểm đến để biết loại hành động.','送 là một chữ đa nghĩa theo khung tân ngữ, không cần bịa một câu chuyện về nét để gom mọi nghĩa.','送你一本书 tặng bạn sách; 送你回家 đưa bạn về nhà. Người nhận quà và người được đưa đi có thể cùng là 你.','“Tống” trong tống tiễn gợi đưa/tiễn; nghĩa tặng học thêm qua 送礼物.', ['我送她一本书。','Wǒ sòng tā yì běn shū.','Tôi tặng cô ấy một cuốn sách.'],['我送你去车站。','Wǒ sòng nǐ qù chēzhàn.','Tôi đưa bạn đến ga.']);
 add('累','Tính từ chỉ trạng thái mệt. 很累 nhận xét mức độ; 累了 có thể báo chuyển sang trạng thái mệt.','累 trong mệt đọc lèi. Không lấy cách đọc hoặc nghĩa từ một tổ hợp khác như 累计 để áp sang câu này.','我累了 là tôi mệt rồi; 我很忙 là tôi bận. Bận có thể dẫn tới mệt nhưng hai từ không đồng nghĩa.','“Lụy” gợi liên hệ trong mệt lụy/liên lụy nhưng không dùng để suy mọi nghĩa; ưu tiên tiếng Việt mệt.', ['走了一个小时，我有点儿累。','Zǒu le yí ge xiǎoshí, wǒ yǒudiǎnr lèi.','Đi bộ một tiếng, tôi hơi mệt.'],['你累不累？先休息一会儿吧。','Nǐ lèi bu lèi? Xiān xiūxi yíhuìr ba.','Bạn có mệt không? Nghỉ một lát trước nhé.']);
 add('商场','Nơi có các cửa hàng phục vụ mua sắm; dùng 去商场、在商场买东西.','商 nêu hoạt động thương mại, 场 nêu nơi diễn ra. Nghĩa ghép giúp nhận loại địa điểm; không xác định thiết kế tòa nhà từ hai chữ.','商场 là khu/trung tâm mua sắm; 商店 là cửa hàng. Một 商场 có thể có nhiều 商店.','“Thương trường” trong tiếng Việt thường chỉ môi trường kinh doanh; 商场 ở câu mua quần áo là địa điểm cụ thể.', ['我们去商场买裤子吧。','Wǒmen qù shāngchǎng mǎi kùzi ba.','Chúng ta đến trung tâm mua sắm mua quần nhé.'],['这家商场里有很多商店。','Zhè jiā shāngchǎng lǐ yǒu hěn duō shāngdiàn.','Trong trung tâm mua sắm này có nhiều cửa hàng.']);
 add('4:过','Đứng sau động từ, 过 nhẹ đánh dấu từng có trải nghiệm tính tới mốc đang nói.','Đây là trợ từ thể, khác động từ 过 guò trong 过生日 và phần chỉ hướng 过来. Cùng chữ không có nghĩa cùng chức năng.','去过北京 nói đã từng đến; 去了北京 thường kể một sự kiện đi hoặc thay đổi tình huống. Tùy ngữ cảnh, hai câu trả lời hai câu hỏi khác nhau.','“Quá” trong quá khứ gợi điều đã qua; trợ từ guo không đơn giản là thì quá khứ của mọi động từ.', ['我去过中国。','Wǒ qù guo Zhōngguó.','Tôi từng đến Trung Quốc.'],['我没吃过这种蛋糕。','Wǒ méi chī guo zhè zhǒng dàngāo.','Tôi chưa từng ăn loại bánh này.']);
 add('进去','Vào bên trong và rời phía người nói/điểm nhìn. Để người và vật ở đâu trên sơ đồ rồi chọn 来/去.','进 nêu qua biên giới vào trong; 去 nêu hướng xa mốc. Không học thành một hình ảnh “đi vào” thiếu vị trí người nói.','Người đứng ngoài nói 你进去吧; người trong phòng gọi 你进来吧.','进 là “tiến” trong tiến vào; nghĩa tiến bộ chỉ là một nhánh khác của chữ.', ['里面有人，我们进去看看吧。','Lǐmian yǒu rén, wǒmen jìnqù kànkan ba.','Bên trong có người, chúng ta vào xem nhé.'],['他走进教室去了。','Tā zǒu jìn jiàoshì qù le.','Anh ấy đi vào phòng học rồi.']);
 add('白色','Tên màu trắng; 白色的 + danh từ hoặc 白色的 thay danh từ đã rõ trong ngữ cảnh.','白 chỉ sắc trắng, 色 chỉ màu: chữ đứng trước xác định màu nào. Không phải mọi tổ hợp với 白 đều nói màu như 明白.','白色的书包 là cặp màu trắng; 我明白了 là tôi hiểu rồi, không liên quan màu của đồ vật.','“Bạch” trong bạch cầu giúp nhận sắc trắng, 色 là “sắc” trong màu sắc.', ['我想买一个白色的书包。','Wǒ xiǎng mǎi yí ge báisè de shūbāo.','Tôi muốn mua một chiếc cặp màu trắng.'],['白色的比较好看。','Báisè de bǐjiào hǎokàn.','Chiếc màu trắng trông đẹp hơn.']);
 add('红色','Tên màu đỏ. Khi danh từ đã xuất hiện, 红色的 có thể chỉ chiếc/cái màu đỏ.','红 bổ nghĩa cho 色. 红 trong cách nói kinh tế/xã hội khác có thể mang nghĩa mở rộng; ở đây bắt đầu từ sắc của đồ vật.','我喜欢红色 nêu màu yêu thích; 我喜欢红色的 nêu đối tượng màu đỏ đã được hiểu từ trước.','“Hồng” trong hồng kỳ, hồng cầu không luôn tương đương màu hồng nhạt tiếng Việt.', ['她穿红色的衣服很好看。','Tā chuān hóngsè de yīfu hěn hǎokàn.','Cô ấy mặc quần áo màu đỏ rất đẹp.'],['你喜欢红色还是白色？','Nǐ xǐhuan hóngsè háishi báisè?','Bạn thích màu đỏ hay trắng?']);
 add('黑色','Tên màu đen. Có thể dùng 黑色的鞋 chỉ đôi giày màu đen.','黑 + 色 là cấu trúc tên màu. Phần 色 chỉ nhóm ý nghĩa màu sắc, không phải bộ thủ của chữ 黑.','黑色 mô tả sắc; 天黑了 nói trời đã tối. Không phải trời chuyển thành một đồ vật màu đen.','“Hắc” trong hắc bạch giúp đối chiếu 黑 với 白.', ['这条黑色的裤子多少钱？','Zhè tiáo hēisè de kùzi duōshao qián?','Chiếc quần đen này bao nhiêu tiền?'],['天黑了，我们回去吧。','Tiān hēi le, wǒmen huíqù ba.','Trời tối rồi, chúng ta về nhé.']);
 add('绿色','Tên màu xanh lá, phân biệt 蓝色 là xanh lam trong cách gọi màu cơ bản hiện đại.','绿 bổ nghĩa cho 色. Lǜ có ü; gõ lv4 khi nhập pinyin số thanh để giữ đúng vần.','绿色 là xanh lá; 青 có phạm vi nghĩa màu trong văn bản cổ rộng hơn, không thay tự do cho tên màu hiện đại.','绿 là “lục” trong lục diệp; tiếng Việt xanh còn cần ngữ cảnh để chọn xanh lá hay xanh lam.', ['我喜欢那个绿色的书包。','Wǒ xǐhuan nà ge lǜsè de shūbāo.','Tôi thích chiếc cặp màu xanh lá kia.'],['你要绿色的，还是蓝色的？','Nǐ yào lǜsè de, háishi lánsè de?','Bạn lấy chiếc xanh lá hay xanh lam?']);
 add('颜色','Danh từ gọi màu sắc nói chung; 什么颜色 hỏi màu nào.','Học 颜色 như một từ quy ước. 颜 còn gặp trong nghĩa sắc mặt/dung nhan, nhưng không dịch tổ hợp này là “mặt màu”.','什么颜色 hỏi thuộc tính màu; 哪个 hỏi chọn đối tượng. Một câu trả lời có thể là 红色, câu kia có thể là 这个.','“Nhan sắc” trong tiếng Việt thiên về vẻ đẹp/dung mạo, không là bản dịch thông thường của 颜色.', ['你喜欢什么颜色？','Nǐ xǐhuan shénme yánsè?','Bạn thích màu gì?'],['这两件衣服的颜色不一样。','Zhè liǎng jiàn yīfu de yánsè bù yíyàng.','Màu của hai chiếc áo này không giống nhau.']);
 add('裤子','Danh từ chỉ quần. Dùng 一条裤子 và 穿裤子; 子 thường đọc nhẹ trong từ này.','裤 là phần mang nghĩa quần, 子 là đuôi danh từ ở đây; không phải “đứa con của quần”. 裤 có giản/phồn 褲.','一条裤子 đếm quần; 一件衣服 đếm áo/đồ mặc. Hai loại đồ mặc có lượng từ điển hình khác nhau.','“Khố” xuất hiện trong từ Việt lịch sử nhưng không chỉ đúng cùng loại trang phục với mọi 裤子 hiện đại.', ['这条裤子有点儿长。','Zhè tiáo kùzi yǒudiǎnr cháng.','Chiếc quần này hơi dài.'],['我想试试那条黑色的裤子。','Wǒ xiǎng shìshi nà tiáo hēisè de kùzi.','Tôi muốn thử chiếc quần đen kia.']);
 add('条','Lượng từ cho những nhóm đối tượng quy ước như quần, cá, đường/sông; nhận qua danh từ cụ thể.','条 có thể gợi vật dài nhưng không phải vật nào dài cũng dùng 条. Chẳng hạn 一支笔 dùng 支.','一条鱼、两条裤子 đều đúng; 一条画笔 không phải mẫu lượng từ thông thường cho bút.','“Điều” trong điều khoản thuộc nhánh khác; một quy tắc tiếng Việt duy nhất không bao trọn lượng từ này.', ['我买了两条裤子。','Wǒ mǎi le liǎng tiáo kùzi.','Tôi mua hai chiếc quần.'],['这条鱼太大了。','Zhè tiáo yú tài dà le.','Con cá này to quá.']);
 add('因为','Giới thiệu lý do. Có thể nêu riêng vế vì hoặc đi với 所以 để làm quan hệ rõ hơn.','因为 là liên từ hai chữ trong cấu trúc đang học. Đừng lấy 为 trong 为什么 rồi coi hai biểu thức có cùng nhiệm vụ.','因为我累了 nêu nguyên nhân; 所以我想休息 nêu kết quả. Cần giữ hướng giải thích thay vì hoán đổi hai vế mà không đổi từ nối.','“Nhân” trong nguyên nhân giúp nhớ 因; không dịch từng chữ thành nhân vi trong lời Việt.', ['因为下雨，我们不出去了。','Yīnwèi xià yǔ, wǒmen bù chūqù le.','Vì trời mưa, chúng tôi không ra ngoài nữa.'],['我想休息，因为我有点儿累。','Wǒ xiǎng xiūxi, yīnwèi wǒ yǒudiǎnr lèi.','Tôi muốn nghỉ vì tôi hơi mệt.']);
 add('所以','Giới thiệu điều xảy ra do nguyên nhân trước đó. Vế trước có thể có 因为 hoặc nguyên nhân đã rõ qua lượt nói.','所以 là một từ nối trong tiếng Trung hiện đại. Không suy rằng 所 luôn có một bản dịch riêng ở bất cứ đâu.','但 tạo tương phản; 所以 tạo kết quả. “Mệt nhưng đi” và “mệt nên nghỉ” không cùng quan hệ.','“Cho nên/vì vậy” là nghĩa dùng; sở dĩ trong tiếng Việt có thể đứng ở vị trí giải thích khác, không thay máy móc.', ['因为车站很远，所以我们打车去。','Yīnwèi chēzhàn hěn yuǎn, suǒyǐ wǒmen dǎchē qù.','Vì ga xa nên chúng tôi đi taxi.'],['我已经吃完了，所以现在不饿。','Wǒ yǐjīng chīwán le, suǒyǐ xiànzài bú è.','Tôi đã ăn xong nên bây giờ không đói.']);
 add('试','Thử một việc/đồ để biết kết quả. 试试 làm giọng đề nghị nhẹ, thường hiểu thử một chút.','试 có thành phần 讠 trong dạng giản; phân tích chức năng của 试一试 cần ở cấp động từ lặp, không ở cấp nét chữ.','试试这件衣服 là thử mặc/xem đồ hợp không; 穿上这件衣服 là mặc nó lên, chưa nói đang thử mua.','“Thí” trong thí nghiệm giúp nhớ việc thử, nhưng 试衣服 không dịch thành thí nghiệm quần áo.', ['我可以试试这件衣服吗？','Wǒ kěyǐ shìshi zhè jiàn yīfu ma?','Tôi có thể thử chiếc áo này không?'],['你先试一下，再决定买不买。','Nǐ xiān shì yíxià, zài juédìng mǎi bu mǎi.','Bạn thử trước rồi quyết định có mua không.']);
 add('书包','Cặp/túi dùng mang sách và đồ học. Trung tâm nghĩa là 包; 书 xác định công dụng điển hình.','Một tổ hợp ghép bổ nghĩa: loại túi liên quan sách. Không suy cứ có sách bên trong mới được gọi 书包.','一本书 đếm cuốn sách; 一个书包 đếm cặp. Danh từ trung tâm quyết định cách đếm.','“Thư” trong thư viện ở đây là sách; 包 nối với bao, túi.', ['我的书包里有三本书。','Wǒ de shūbāo lǐ yǒu sān běn shū.','Trong cặp tôi có ba cuốn sách.'],['这个书包太小了。','Zhè ge shūbāo tài xiǎo le.','Chiếc cặp này nhỏ quá.']);
 add('过去','Ở bài này, đi qua bên kia, xa mốc nhìn. Trong một khung khác, 过去 có thể là thời gian quá khứ.','过 + 去 chỉ hướng ở 走过去; danh từ/thành phần thời gian trong 过去的事 có cấu trúc khác.','他走过去了 kể chuyển động; 过去他住这里 kể thời trước. Từ đứng cạnh quyết định nghĩa.','“Quá khứ” là từ Hán Việt có cùng chữ 過去, nhưng không phải bản dịch cho 走过去.', ['饭店在那边，我们走过去吧。','Fàndiàn zài nà biān, wǒmen zǒu guòqù ba.','Nhà hàng ở đằng kia, chúng ta đi bộ qua nhé.'],['过去我住在北京。','Guòqù wǒ zhù zài Běijīng.','Trước đây tôi sống ở Bắc Kinh.']);
 add('更','Trước tính từ/động từ trạng thái để so mức độ: 更好、更喜欢. Mốc so sánh có thể nêu ra hoặc ngầm hiểu.','更 là phó từ một chữ, không phải hậu tố đứng sau tính từ như từ “hơn” trong tiếng Việt.','A比B更远 nói A còn xa hơn B. 很远 chỉ mức xa cao, chưa tự xác lập một vật để so.','“Cánh” của 更 ít quen thuộc; nhớ vị trí 更 + tính từ thay vì ghép âm Hán Việt.', ['这条裤子更好看。','Zhè tiáo kùzi gèng hǎokàn.','Chiếc quần này trông đẹp hơn.'],['我更喜欢绿色的。','Wǒ gèng xǐhuan lǜsè de.','Tôi thích chiếc màu xanh lá hơn.']);
 add('快','Nhanh là cách thực hiện; 快 + động từ còn có thể thúc mau làm. 快…了 lại báo sắp đến một tình huống.','Một chữ xuất hiện trong ba khung ngữ pháp. Không lấy nghĩa “vui” từ 快乐 để dịch 快走.','走得快 là đi nhanh; 快走！ là mau đi; 快到了 là sắp tới nơi.','“Khoái” trong khoái cảm gợi một nhánh nghĩa khác; câu nhanh/chậm cần cặp 快/慢.', ['快进来，外面很冷。','Kuài jìnlái, wàimian hěn lěng.','Mau vào đây, ngoài trời lạnh lắm.'],['他走得比我快。','Tā zǒu de bǐ wǒ kuài.','Anh ấy đi nhanh hơn tôi.']);
 add('下来','Xuống và hướng tới mốc. Người dưới chân cầu thang có thể gọi 上面的人下来.','下 chọn chiều từ cao xuống thấp, 来 chọn điểm đến về phía mốc. Trong 坐下来, cả tổ hợp còn diễn tả việc ngồi xuống, không chỉ đường di chuyển.','我在楼下，你下来吧 đối lập 我在楼上，你上来吧. Đổi vị trí mốc sẽ đổi chiều cao chứ không phải chỉ đổi động từ “đi”.','“Hạ” trong hạ xuống gợi chiều; 来 vẫn phải chọn theo người nói.', ['我在楼下，你下来吧。','Wǒ zài lóuxià, nǐ xiàlái ba.','Tôi ở dưới tầng, bạn xuống đây nhé.'],['请坐下来喝杯茶。','Qǐng zuò xiàlái hē bēi chá.','Mời bạn ngồi xuống uống chén trà.']);
 add('下去','Xuống xa phía mốc. Người ở trên có thể bảo người bên cạnh đi xuống dưới.','下 + 去 góp hai trục cao/thấp và về/xa mốc. 说下去 còn là nghĩa tiếp diễn, không có cầu thang vật lý.','下来 là xuống đây; 下去 là xuống đó. Có thể cần sơ đồ vị trí chứ không một từ tiếng Việt “xuống”.','“Hạ” giúp nhận chiều xuống; không coi mọi 下去 đều là chuyển động không gian.', ['老师在楼下，你下去找他吧。','Lǎoshī zài lóuxià, nǐ xiàqù zhǎo tā ba.','Thầy ở tầng dưới, bạn xuống tìm thầy nhé.'],['请说下去。','Qǐng shuō xiàqù.','Bạn nói tiếp đi.']);
 add('上来','Lên và hướng về phía mốc. Người đang trên tầng gọi người dưới lên đây.','上 đặt chiều đi lên; 来 nêu hướng về mốc. Đừng hiểu 来 luôn đồng nghĩa “đến nhà của tôi”; mốc có thể là vị trí hiện thời.','上来 và 上去 cùng đi lên nhưng khác nơi người nói/điểm nhìn đang đứng.','“Thượng” trong thượng tầng gợi phía trên, còn 来 quyết định về phía ai.', ['我在三楼，你上来吧。','Wǒ zài sān lóu, nǐ shànglái ba.','Tôi ở tầng ba, bạn lên đây nhé.'],['他从楼下跑上来了。','Tā cóng lóuxià pǎo shànglái le.','Anh ấy chạy từ dưới tầng lên đây rồi.']);
 add('上去','Lên và đi ra xa mốc nhìn. Người dưới tầng có thể nhờ ai mang sách lên chỗ khác.','上 + 去 là hướng kép: cao hơn và xa mốc. Đặt nơi đến trong cấu trúc 上楼去 để thấy vai của từng yếu tố.','上来 gọi người lên nơi mình; 上去 chỉ đi lên bên kia. Không thể chọn chỉ bằng nghĩa của 上.','Đối chiếu “thượng” để nhận 上; lời Việt “lên đó” giúp biểu đạt thêm 去.', ['他在楼上，你上去看看吧。','Tā zài lóushàng, nǐ shàngqù kànkan ba.','Anh ấy ở trên tầng, bạn lên đó xem nhé.'],['请把书拿上去。','Qǐng bǎ shū ná shàngqù.','Bạn vui lòng mang sách lên đó.']);
 add('下面','Danh từ phương vị: phần/phía dưới của một mốc. Mốc có thể là cái bàn, trang giấy, tòa nhà hoặc bước sau trong phát biểu.','下 chỉ quan hệ dưới, 面 trong từ này giúp tạo biểu thức phương vị; khác 面 là mì.','桌子下面 nói vị trí dưới bàn; 面很好吃 nói món mì ngon. Không chọn nghĩa chỉ vì cùng một chữ 面.','“Hạ diện” là đối chiếu chữ, lời Việt tự nhiên là phía dưới/bên dưới.', ['猫在桌子下面。','Māo zài zhuōzi xiàmian.','Con mèo ở dưới bàn.'],['请看下面的句子。','Qǐng kàn xiàmian de jùzi.','Bạn hãy xem câu ở phía dưới.']);
 add('等','Đợi ai hoặc việc gì: 等你、等车. 等一下/等一会儿 là chờ một chút.','等 là động từ trong bài. Trong 等等 cuối danh sách, nó lại mở ý “vân vân”, khác chức năng.','我等你 là tôi chờ bạn; 你等我 là bạn chờ tôi. Hai người đổi vị trí là đổi vai, không đổi nghĩa của 等.','“Đẳng” trong đẳng cấp, bình đẳng thuộc các nghĩa khác; không ép chúng thành nghĩa đợi.', ['我在门口等你。','Wǒ zài ménkǒu děng nǐ.','Tôi đợi bạn ở cửa.'],['等一下，我还没准备好。','Děng yíxià, wǒ hái méi zhǔnbèi hǎo.','Chờ một chút, tôi chưa chuẩn bị xong.']);
 add('一会儿','Một khoảng thời gian ngắn, độ dài tùy tình huống. Có thể đứng sau hành động hoặc trong 一会儿再….','一 + 会儿 tạo biểu thức thời lượng; 儿 ở đây thường làm âm hóa r của vần, không tách thành âm ér độc lập.','等一会儿 là đợi một lát; 一会儿再走 là lát nữa mới đi. Cùng cụm nhưng vị trí làm rõ nó kéo dài việc đợi hay đặt mốc đi sau.','Không dùng “một hội nhi” làm nghĩa; học bằng đối chiếu một lát/lát nữa.', ['请等一会儿。','Qǐng děng yíhuìr.','Bạn đợi một lát nhé.'],['我一会儿再给你打电话。','Wǒ yíhuìr zài gěi nǐ dǎ diànhuà.','Lát nữa tôi gọi lại cho bạn.']);
 add('进来','Vào trong và hướng tới phía người nói/mốc nhìn. Điển hình là lời mời của người ở trong phòng.','进 nêu qua cửa vào trong; 来 nêu hướng về đây. Một cửa nhưng người đứng hai phía sẽ chọn 来/去 khác nhau.','请进来 là mời vào đây; 请进去 là bảo đi vào đó.','进 là “tiến” trong tiến vào; trong cặp hướng, cần học cả 来/去.', ['门开着，请进来吧。','Mén kāizhe, qǐng jìnlái ba.','Cửa đang mở, mời vào đây.'],['他走进房间来了。','Tā zǒu jìn fángjiān lái le.','Anh ấy đi vào phòng, về phía đây rồi.']);
 add('爷爷','Ông nội trong cách gọi quan hệ gia đình cơ bản; trong một số tình huống còn là cách gọi người đàn ông cao tuổi.','Lặp âm tiết tạo tên gọi thân tộc; âm tiết sau thường nhẹ. Không cộng hai chữ 爷 thành “hai ông”.','爷爷 là ông phía cha; 外公 thường gọi ông phía mẹ. Trong bài gia đình cần nêu đúng quan hệ.','Chữ “gia” này là 爺, không phải 家 trong gia đình. Hai âm Hán Việt giống không có nghĩa cùng chữ.', ['我爷爷住在北京。','Wǒ yéye zhù zài Běijīng.','Ông nội tôi sống ở Bắc Kinh.'],['爷爷，生日快乐！','Yéye, shēngrì kuàilè!','Ông ơi, chúc ông sinh nhật vui vẻ!']);
 add('奶奶','Bà nội trong quan hệ gia đình cơ bản. Âm tiết sau thường nhẹ; không đọc nó như một từ sữa riêng trong câu.','Tên gọi thân tộc có dạng lặp. 奶 trong 奶茶 là sữa, nhưng 奶奶 là từ xưng gọi đã quy ước.','奶奶 và 外婆 phân biệt phía nội/ngoại trong cách gọi phổ biến; cách xưng hô thực tế có thể khác theo vùng.','Không lấy một âm Hán Việt ít gặp để dựng nghĩa; liên hệ bà nội với 爷爷 là cặp hữu ích hơn.', ['我想给奶奶买一份礼物。','Wǒ xiǎng gěi nǎinai mǎi yí fèn lǐwù.','Tôi muốn mua cho bà nội một món quà.'],['奶奶正在喝茶。','Nǎinai zhèngzài hē chá.','Bà nội đang uống trà.']);
 add('礼物','Đồ được chuẩn bị hoặc trao tặng; 一份礼物、送礼物 là các kết hợp thường dùng.','礼 gắn với việc lễ/tặng, 物 là vật: ghép nghĩa giúp nhận loại đồ, nhưng không buộc món quà phải có tính nghi lễ trang trọng.','买礼物 là mua quà; 送礼物 là tặng quà. Mua xong chưa xác nhận đã trao cho người nhận.','“Lễ vật” là từ Việt có cùng chữ, thường trang trọng hơn nghĩa quà trong sinh nhật hằng ngày.', ['这是我送给你的礼物。','Zhè shì wǒ sòng gěi nǐ de lǐwù.','Đây là món quà tôi tặng bạn.'],['你准备了什么生日礼物？','Nǐ zhǔnbèi le shénme shēngrì lǐwù?','Bạn đã chuẩn bị quà sinh nhật gì?']);
 add('准备','Có thể là chuẩn bị vật/điều kiện hoặc dự định làm việc: 准备礼物、准备去旅游.','Học 准备 như một động từ hai chữ. Nghĩa “chuẩn” đúng/mức chuẩn của 准 trong từ khác không dịch riêng vào đây.','准备了礼物 là đã chuẩn bị quà; 准备买礼物 có thể mới dự định mua, chưa có quà.','“Chuẩn bị” là từ Hán Việt đang dùng trực tiếp và là điểm nối tốt; vẫn phải nhìn tân ngữ/cấu trúc để biết đã làm hay dự định.', ['我正在准备明天的课。','Wǒ zhèngzài zhǔnbèi míngtiān de kè.','Tôi đang chuẩn bị bài cho ngày mai.'],['我们准备下个月去旅游。','Wǒmen zhǔnbèi xià ge yuè qù lǚyóu.','Chúng tôi dự định tháng sau đi du lịch.']);
 add('奶茶','Đồ uống trà có sữa theo tên gọi cơ bản; một cốc thường nói 一杯奶茶.','奶 bổ nghĩa cho 茶 để tạo tên đồ uống. Tên này không tự xác nhận có trân châu, đường hay loại sữa nào.','奶茶 là trà sữa; 牛奶 là sữa bò. Thành phần chung 奶 không khiến hai đồ uống thay thế tự do.','茶 là “trà”; 奶奶 có cùng chữ 奶 nhưng là cách gọi bà, không phải một loại đồ uống.', ['你想喝奶茶还是喝水？','Nǐ xiǎng hē nǎichá háishi hē shuǐ?','Bạn muốn uống trà sữa hay nước?'],['我给你买了一杯热奶茶。','Wǒ gěi nǐ mǎi le yì bēi rè nǎichá.','Tôi mua cho bạn một cốc trà sữa nóng.']);
 add('跟','Giới thiệu người cùng làm hoặc người đi theo. Có thể làm động từ theo hoặc thành phần nối “với”.','Cùng chữ nhưng khung khác: 跟着老师走 nêu theo thầy; 跟老师一起走 nêu đi cùng thầy.','我跟他去 là tôi đi với anh ấy; 我给他送书 là tôi mang sách cho anh ấy. Không đổi 跟/给 chỉ vì cùng có người sau nó.','Âm “cân” của 跟 không phải “cân” 斤 đo khối lượng; quan hệ với/đi theo hữu ích hơn việc ghép âm.', ['我跟朋友一起去。','Wǒ gēn péngyou yìqǐ qù.','Tôi đi cùng bạn.'],['请跟我走。','Qǐng gēn wǒ zǒu.','Bạn vui lòng đi theo tôi.']);
 add('走','Đi bộ, bước đi hoặc rời nơi đang ở. Kết hợp từ sau để biết đang đi đâu hay sắp rời đi.','走 là động từ một chữ. Trong lời hiện đại, 跑 thường là chạy; không lấy nghĩa cổ của 走 áp sang mọi câu.','我走了 có thể là tôi đi đây; 我走路去 nêu đi bộ. Chỉ nghe một chữ 走 chưa đủ xác định phương tiện cả chặng.','“Tẩu” trong tẩu thoát gợi rời đi; đừng dịch mọi 走 thành chạy trốn.', ['我们走路去饭店吧。','Wǒmen zǒulù qù fàndiàn ba.','Chúng ta đi bộ tới nhà hàng nhé.'],['太晚了，我先走了。','Tài wǎn le, wǒ xiān zǒu le.','Muộn quá, tôi đi trước đây.']);
 add('酒店','Trong ngữ cảnh chuyến đi, 酒店 là khách sạn. Có thể nói 订酒店、住酒店.','酒 + 店 không buộc cả từ hiện đại là cửa hàng bán rượu. Đây là ví dụ cần tra nghĩa cả từ trước khi suy từng chữ.','酒店 thường chỉ nơi lưu trú; 饭店 có thể là nhà hàng hoặc khách sạn trong tên gọi cụ thể. Xem đang đặt phòng hay gọi món.','“Tửu điếm” là đối chiếu chữ, tiếng Việt hiện đại thường dịch khách sạn.', ['我们住在车站旁边的酒店。','Wǒmen zhù zài chēzhàn pángbiān de jiǔdiàn.','Chúng tôi ở khách sạn cạnh ga.'],['你在网上订好酒店了吗？','Nǐ zài wǎngshang dìnghǎo jiǔdiàn le ma?','Bạn đã đặt xong khách sạn trên mạng chưa?']);
 add('面','Trong bài ăn uống, 面 là mì. Ở biểu thức phương vị như 下面, chữ 面 có nghĩa và chức năng khác.','Mì viết phồn thể 麵, giản thể là 面. “Mặt/bề mặt” cũng viết 面, nên dạng giản thể đã làm hai trường hợp gặp nhau.','吃面 là ăn mì; 在下面 là ở dưới. Xem động từ hoặc cụm vị trí trước khi chọn nghĩa.','Mì có thể gợi 面 trong bối cảnh ăn; “diện” trong diện mạo thuộc nghĩa mặt, không phải món ăn.', ['中午我想吃面。','Zhōngwǔ wǒ xiǎng chī miàn.','Trưa tôi muốn ăn mì.'],['这家饭店的面很好吃。','Zhè jiā fàndiàn de miàn hěn hǎochī.','Mì ở nhà hàng này rất ngon.']);
 add('生日','Ngày sinh hoặc dịp sinh nhật hằng năm. 过生日 là mừng/đón sinh nhật; 生日快乐 là lời chúc.','生 liên quan sinh ra, 日 là ngày; ghép nghĩa này tương ứng khá trực tiếp với “sinh nhật”.','我的生日是五月三日 nêu ngày; 我们明天过生日 nêu hoạt động đón/mừng. Ngày và cách mừng có thể không trùng đúng một hôm.','“Sinh nhật” là từ Hán Việt trực tiếp, nên là cầu nối chắc hơn mọi mẹo chia nét 生.', ['你的生日是几月几号？','Nǐ de shēngrì shì jǐ yuè jǐ hào?','Sinh nhật bạn là ngày mấy tháng mấy?'],['我们想给她过生日。','Wǒmen xiǎng gěi tā guò shēngrì.','Chúng tôi muốn tổ chức sinh nhật cho cô ấy.']);
 add('快乐','Tính từ chỉ vui vẻ/hạnh phúc, thường gặp trong lời chúc. 祝你…快乐 là một khung sử dụng.','Đây là từ hai chữ, không suy nghĩa “nhanh” của 快 vào 快乐. 乐 ở đây đọc lè, khác yuè trong 音乐.','快乐 nói trạng thái vui; 高兴 thường diễn tả vui trước một điều/sự kiện cụ thể. Phạm vi giao nhau nhưng không đổi mọi kết hợp được.','“Khoái lạc” là cách đọc Hán Việt, nhưng tiếng Việt có sắc thái khác; lời chúc tự nhiên là sinh nhật vui vẻ.', ['祝你生日快乐！','Zhù nǐ shēngrì kuàilè!','Chúc bạn sinh nhật vui vẻ!'],['我希望你每天都快乐。','Wǒ xīwàng nǐ měitiān dōu kuàilè.','Tôi mong bạn ngày nào cũng vui.']);
 add('忘','Quên một thông tin hoặc việc cần làm. 别忘了… nhắc đừng quên; 忘带… là quên mang.','忘 là động từ. Hình trên có 亡 dưới có 心 trong chữ hiện đại; câu “mất tâm là quên” chỉ là mẹo nếu không có chứng cứ lịch sử kèm theo.','忘带票 là quên mang vé; 丢了票 là làm mất vé. Quên hành động và làm thất lạc đồ không đồng nghĩa.','“Vong” trong lãng vong ít dùng; có thể đối chiếu 忘 với 记得 thay vì buộc phải học một từ Việt hiếm.', ['别忘了明天是她的生日。','Bié wàng le míngtiān shì tā de shēngrì.','Đừng quên ngày mai là sinh nhật cô ấy.'],['我忘带书包了。','Wǒ wàng dài shūbāo le.','Tôi quên mang cặp rồi.']);
 add('画','画画 là vẽ tranh: 画 thứ nhất là động từ, 画 thứ hai là danh từ; 一幅画 đếm một bức tranh.','Cùng chữ có thể làm động từ hoặc danh từ. Hai chữ cạnh nhau không phải lúc nào cũng là lặp động từ để làm nhẹ.','他画了一张画 có hành động vẽ và sản phẩm; 试试 thì hai 试 là lặp cùng động từ. Cần xét vai trò thay vì chỉ nhìn lặp mặt chữ.','“Họa” trong hội họa, họa sĩ liên quan vẽ; 画不是 họa trong tai họa 禍.', ['她正在画一只猫。','Tā zhèngzài huà yì zhī māo.','Cô ấy đang vẽ một con mèo.'],['这幅画是我自己画的。','Zhè fú huà shì wǒ zìjǐ huà de.','Bức tranh này do chính tôi vẽ.']);
 add('画笔','Bút dùng để vẽ; khi đếm thường dùng 支.','画 nêu công dụng của 笔, phần trung tâm là bút. Đây là ghép từ, khác việc phân tích cấu tạo bên trong chữ 笔.','画笔 là bút vẽ; 画一支笔 là vẽ hình một chiếc bút. Danh từ ghép và động từ mang tân ngữ không có cùng cấu trúc.','“Họa bút” là đối chiếu chữ; tiếng Việt thường nói bút vẽ.', ['我想买一支画笔。','Wǒ xiǎng mǎi yì zhī huàbǐ.','Tôi muốn mua một cây bút vẽ.'],['这支画笔是老师送的。','Zhè zhī huàbǐ shì lǎoshī sòng de.','Cây bút vẽ này là thầy cô tặng.']);
 add('蛋糕','Bánh ngọt/bánh kem theo loại thường gọi là cake; 生日蛋糕 là bánh sinh nhật.','蛋 bổ nghĩa cho 糕 trong tên loại bánh. Tên gọi hiện đại không là bảng thành phần chứng minh mọi sản phẩm đều chứa trứng.','一个蛋糕 là cả chiếc; 一块蛋糕 là một miếng. Lượng từ đổi cách chia vật, không làm đổi loại bánh.','“Cao” của 糕 khác 高 cao/thấp, dù cùng âm gāo. Ghi nhớ bằng cặp chữ để tránh viết nhầm.', ['我们买了一个生日蛋糕。','Wǒmen mǎi le yí ge shēngrì dàngāo.','Chúng tôi mua một chiếc bánh sinh nhật.'],['你想吃一块蛋糕吗？','Nǐ xiǎng chī yí kuài dàngāo ma?','Bạn có muốn ăn một miếng bánh không?']);
 add('打开','Mở ra vật đóng, bao gói hoặc thiết bị/tài liệu theo ngữ cảnh: 打开门、打开礼物.','开 biểu đạt kết quả mở trong tổ hợp quen dùng 打开. Không gán nghĩa đánh của 打 vào thao tác mở quà.','打开书 là mở sách, 看书 là đọc sách. Mở vật để đọc chưa đồng nghĩa đã đọc hiểu hoặc đọc xong.','“Đả khai” có thể dùng để nhận chữ nhưng không phải lời Việt thường dùng cho mở ra.', ['她打开了我送的礼物。','Tā dǎkāi le wǒ sòng de lǐwù.','Cô ấy mở món quà tôi tặng ra.'],['请打开书，看第二页。','Qǐng dǎkāi shū, kàn dì èr yè.','Bạn mở sách ra, xem trang hai.']);
 add('长','Nghĩa dài đọc cháng, có thể nói đường, quần, đoạn văn hoặc khoảng thời gian dài.','长 là chữ đa âm: cháng trong 很长, zhǎng trong 长大. Khác nghĩa/chức năng có thể đi cùng khác cách đọc.','这条裤子很长 nói chiều dài; 孩子长大了 nói đứa trẻ lớn lên. Không đoán âm chỉ từ hình chữ.','“Trường” trong trường thọ gợi dài/lâu; “trưởng” trong trưởng thành gắn với cách dùng lớn lên.', ['这条路很长。','Zhè tiáo lù hěn cháng.','Con đường này rất dài.'],['这条裤子太长了，我想试短一点儿的。','Zhè tiáo kùzi tài cháng le, wǒ xiǎng shì duǎn yìdiǎnr de.','Quần này dài quá, tôi muốn thử chiếc ngắn hơn một chút.']);
 add('鱼','Cá, làm thức ăn hoặc con vật. Lượng từ 条 thường dùng cho một con cá trong các câu cơ bản.','鱼 giản thể của 魚. Nhận dạng giản/phồn là một việc; xác định cả từ như 鱼肉 thịt cá là việc khác.','一条鱼 đếm con cá; 一块鱼肉 đếm miếng thịt cá. Danh từ trung tâm và cách chia vật quyết định lượng từ.','“Ngư” trong ngư dân, ngư nghiệp giúp nối chữ với nghề cá.', ['我买了一条鱼。','Wǒ mǎi le yì tiáo yú.','Tôi mua một con cá.'],['你喜欢吃鱼还是吃肉？','Nǐ xǐhuan chī yú háishi chī ròu?','Bạn thích ăn cá hay thịt?']);
 add('肉','Thịt; loại con vật hoặc phần thân thể trước 肉 có thể xác định loại thịt.','肉 có thể đứng riêng trong ngữ cảnh đã rõ hoặc trong 猪肉、牛肉、鱼肉. Không mặc định mọi 肉 đều là thịt lợn nếu không có ngữ cảnh.','鱼 là con cá/cá làm món; 鱼肉 nói phần thịt cá. Cùng đồ ăn nhưng cách gọi chọn phạm vi khác.','“Nhục” trong cốt nhục liên quan thịt/thân thể; không phải nhục trong sỉ nhục 辱.', ['这家饭店的牛肉很好吃。','Zhè jiā fàndiàn de niúròu hěn hǎochī.','Thịt bò ở nhà hàng này rất ngon.'],['今天我们吃鱼、肉什么的。','Jīntiān wǒmen chī yú, ròu shénme de.','Hôm nay chúng tôi ăn cá, thịt và những món tương tự.']);
 add('6:过','过生日、过年 nói đón/trải qua một dịp. 过 ở đây là động từ mang tân ngữ, đọc đầy đủ guò.','Phân biệt động từ 过 guò với trợ từ trải nghiệm guo sau động từ và hướng 过 trong 过来.','我过生日 nói mừng sinh nhật; 我去过北京 nói từng đến Bắc Kinh. Chọn guò/guo theo chức năng, không gắn cố định một âm cho mọi chỗ.','“Quá” gợi trải qua; không chỉ thấy 过 là dịch “đã từng”.', ['你想怎么过生日？','Nǐ xiǎng zěnme guò shēngrì?','Bạn muốn mừng sinh nhật thế nào?'],['我们回家过年。','Wǒmen huí jiā guò nián.','Chúng tôi về nhà đón Tết.']);
 add('地','Nối cách thức với hành động: 高兴地说、慢慢地走. Đọc nhẹ de trong khung này.','Đây là trợ từ kết cấu, không phải danh từ 地 dì nghĩa đất. Nhận âm phải dựa vào vai trò và từ đứng sau.','高兴地说: vui vẻ là cách nói; 高兴的孩子: vui vẻ mô tả đứa trẻ; 说得很好: phần sau đánh giá kết quả/cách nói.','“Địa” trong địa lý gắn với dì; không dùng âm ấy cho trợ từ de.', ['她高高兴兴地打开了礼物。','Tā gāogāoxìngxìng de dǎkāi le lǐwù.','Cô ấy vui vẻ mở quà ra.'],['爷爷慢慢地走过来。','Yéye mànmàn de zǒu guòlái.','Ông nội từ từ đi qua đây.']);
 add('床','Giường, dùng trong 床上、上床、起床. Động từ và vị trí quyết định ý cả cụm.','床 là danh từ một chữ. 上床 là hành động lên giường, 床上 là vị trí trên giường; đổi thứ tự sẽ đổi cấu trúc.','他在床上 chỉ vị trí; 他要上床睡觉 nói anh ấy chuẩn bị lên giường ngủ.','“Sàng” như giường sàng là âm đối chiếu ít gặp; không bắt thuộc từ Việt hiếm để học danh từ quen.', ['猫在床下面。','Māo zài chuáng xiàmian.','Con mèo ở dưới giường.'],['我想上床休息一会儿。','Wǒ xiǎng shàng chuáng xiūxi yíhuìr.','Tôi muốn lên giường nghỉ một lát.']);
 add('舒服','Tính từ nói cảm giác dễ chịu/thoải mái. 不舒服 còn là cách nói thấy trong người không khỏe.','舒服 là từ hai chữ thường đọc nhẹ âm sau. Trong 舒舒服服, dạng lặp có thể diễn tả trạng thái/cách thức rõ hơn, nhưng không áp kiểu lặp này cho mọi tính từ.','我不舒服 có thể báo không khỏe; 我不高兴 là không vui. Thân thể khó chịu và cảm xúc buồn/bực cần hỏi thêm ngữ cảnh.','舒 gợi thư trong thư thái; 服 ở đây không dịch thành trang phục riêng lẻ.', ['这张床很舒服。','Zhè zhāng chuáng hěn shūfu.','Chiếc giường này rất dễ chịu.'],['我今天有点儿不舒服。','Wǒ jīntiān yǒudiǎnr bù shūfu.','Hôm nay tôi hơi khó chịu trong người.']);
 const byKey=new Map(rows.map(r=>[r.han,r]));
 const book=['Giáo trình đối chiếu · 新HSK教程2','https://heep.fltrp.com/contents/475469828451340288'];
 for(const u of window.HAN_HSK2.units)for(const w of u.words){const r=byKey.get(u.id+':'+w.han)||byKey.get(w.han);if(!r)throw Error('Missing authored study: '+u.id+':'+w.han);const s={...r,han:w.han,lesson:u.id,key:w.key,links:[book],article:w.han==='地'||w.han==='过'?'neutral-tone':''};w.study=s;w.context=r.examples[0][0];w.contextPy=r.examples[0][1];w.contextVn=r.examples[0][2];w.sourceContext=r.examples[0][0];
  const entry=window.HAN_DATA.words.find(x=>x.id===w.catalogId);entry.usageStudies??=[];entry.usageStudies.push(s);entry.studyExamples??=[];for(const ex of r.examples)if(!entry.studyExamples.some(e=>e[0]===ex[0]))entry.studyExamples.push(ex);
  if(!window.HAN_STUDIES.has(w.han))window.HAN_STUDIES.set(w.han,{lead:r.usage,body:[r.formation,r.contrast,r.bridge],links:[book],article:s.article});
 }
 window.HAN_HSK2_STUDIES={rows,byKey,authored:true};
})();
